<template>
 <section class="task-workbench">
  <div class="task-list-heading"><div><h2>{{q.classId ? selectedClass?.name || '班级任务' : '训练任务'}}</h2></div><div class="task-heading-actions"><button :disabled="loading" @click="$emit('refresh')">刷新</button><RouterLink class="primary" :to="{path:'/teacher/tasks/create',query:{classId:q.classId,returnTo:route.fullPath}}">创建训练任务</RouterLink></div></div>
  <div v-if="!q.classId" class="task-class-directory"><div class="task-directory-heading"><h3>我的教学班</h3><span>{{classes.length}} 个教学班</span></div><div class="class-directory-tools"><label><span class="task-search-label">搜索班级</span><input aria-label="搜索班级" type="search" :value="q.classSearch||''" placeholder="输入班级名称或学期" @input="set({classSearch:$event.target.value||undefined})"/></label><div class="class-layout-toggle" role="group" aria-label="班级展示方式"><button :aria-pressed="classLayout==='cards'" @click="changeClassLayout('cards')">卡片展示</button><button :aria-pressed="classLayout==='list'" @click="changeClassLayout('list')">折叠为列表</button></div></div><p v-if="q.classSearch" class="task-list-caption" role="status">找到 {{filteredClasses.length}} / {{classes.length}} 个教学班</p><div class="task-class-grid" :class="{'compact-list':classLayout==='list'}"><RouterLink v-for="(c,index) in filteredClasses" :key="c.id" class="task-class-entry" :class="'class-tone-'+index%3" :to="{path:'/teacher/tasks',query:{classId:c.id,classSearch:q.classSearch}}"><div class="task-class-cover"><span>{{c.semester||'未设置学期'}}{{c.archived?' · 已归档':''}}</span><h3>{{c.name}}</h3><p>管理训练安排，跟进学生执行</p><span class="task-decoration members" aria-hidden="true"/></div><div class="task-class-body"><div class="task-class-facts"><span><b>{{classTasks(c).filter(t=>t.lifecycle==='ACTIVE').length}}</b>进行中任务</span><span><b>{{classTasks(c).length}}</b>全部任务</span><span><b>{{c.joinedCount||0}}</b>当前学生</span></div><div class="task-class-bottom"><strong>{{rate(classTasks(c))}}<small>已发布任务完成率</small></strong><span class="task-class-enter">进入班级</span></div></div></RouterLink></div><div v-if="classes.length&&!filteredClasses.length" class="task-workbench-empty"><h3>没有找到匹配的班级</h3><p>请尝试其他班级名称或学期。</p><button @click="set({classSearch:undefined})">清除班级搜索</button></div><div v-if="!classes.length" class="task-workbench-empty"><span class="task-decoration members" aria-hidden="true"/><h3>还没有教学班级</h3><p>先创建班级并邀请学生，再发布训练任务。</p><RouterLink to="/teacher/classes">管理教学班级 →</RouterLink></div></div>
  <template v-else><div class="task-class-context"><button @click="set({classId:undefined,search:undefined,lifecycle:undefined,view:undefined,completionTask:undefined})">← 全部班级</button><span>{{selectedClass?.semester}}</span></div>
  <section class="class-task-completion" aria-label="班级任务完成情况"><div class="class-completion-heading"><div><h3>{{q.completionTask?'所选任务完成情况':'本班全部任务完成情况'}}</h3><p>截至当前 · 仅统计已发布任务 · 排除减免分配</p></div><label>完成率统计任务<select aria-label="完成率统计任务" :value="q.completionTask||''" @change="set({completionTask:$event.target.value||undefined})"><option value="">全部已发布任务</option><option v-for="t in publishedClassTasks" :key="t.id" :value="String(t.id)">{{t.title}}</option></select></label></div><div class="class-completion-body"><strong class="class-completion-rate">{{rate(completionTasks)}}<small>次数要求完成率</small></strong><div class="class-completion-distribution"><div class="class-completion-bar" role="img" :aria-label="completionStates.map(s=>s.name+' '+s.count+' 人次').join('，')"><i v-for="state in completionStates" :key="state.key" :style="{width:(completionTotal?state.count/completionTotal*100:0)+'%',background:state.color}"/></div><div class="class-completion-legend"><span v-for="state in completionStates" :key="state.key"><i :style="{background:state.color}"/>{{state.name}} {{state.count}} 人次</span></div><p>{{completionDone}} / {{completionTotal}} 人次分配已完成；同一学生参与多项任务分别计数。</p></div></div><p v-if="!completionTotal">{{q.completionTask?'此任务暂无计入统计的参与学生。':'本班暂无已发布任务分配，发布后显示完成率。'}}</p><small>搜索与状态标签仅筛选下方任务列表，不改变此处统计。完成训练要求不等于能力达标。</small></section>
  <form class="task-workbench-tools" @submit.prevent>
   <label>搜索任务<input type="search" :value="q.search||''" placeholder="任务名称或岗位" @input="set({search:$event.target.value||undefined})"/></label>
   <label>教学班级<select :value="q.classId||''" @change="set({classId:$event.target.value||undefined,completionTask:undefined,search:undefined,lifecycle:undefined,view:undefined})"><option value="">全部班级</option><option v-for="c in classes" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label>
   <label>排序<select :value="q.sort||'deadline'" @change="set({sort:$event.target.value})"><option value="deadline">截止最近</option><option value="published">最新发布</option><option value="unfinished">待完成人数最多</option></select></label>
  </form>
  <nav class="task-workbench-tabs" aria-label="任务状态筛选"><button v-for="tab in tabs" :key="tab.key" :aria-pressed="!overdueView && (q.lifecycle||'')===tab.key" @click="set({lifecycle:tab.key||undefined,view:undefined})">{{tab.name}} <span>{{matches.filter(t=>belongs(t,tab.key)).length}}</span></button><button :aria-pressed="overdueView" @click="set({lifecycle:undefined,view:'overdue'})">逾期未完成 <span>{{overdueRows.length}} 人次</span></button></nav>
  <p class="task-list-caption">{{overdueView?'逾期未完成分配 '+overdueRows.length+' 人次':'当前 '+rows.length+' 项任务'}} · 执行截至当前，完成要求与能力达标分别统计</p>
  <div v-if="overdueView && overdueRows.length" class="task-workbench-list"><article v-for="row in overdueRows" :key="row.a.id" class="task-entry"><div class="task-entry-name"><h3>{{row.a.name}}</h3><p>{{row.t.title}} · {{row.t.className}}</p></div><div class="task-entry-time"><span>个人截止</span><strong>{{date(row.a.effectiveDeadline||row.t.deadline)}}</strong></div><div class="task-entry-execution"><strong>{{row.a.validCount||0}} / {{row.t.minAttempts}} 次有效训练</strong><small>尚未完成次数要求</small></div><RouterLink :to="target(row.t,{execution:'overdue',assignmentId:row.a.id})">查看学生分配 →</RouterLink></article></div>
  <div v-else-if="!overdueView && rows.length" class="task-workbench-list"><article v-for="t in rows" :key="t.id" class="task-entry"><div class="task-entry-name task-identity"><span class="task-decoration" :class="/表达|面试/.test(t.title) ? 'expression' : 'briefcase'" aria-hidden="true"/><div><span class="task-entry-status" :class="{draft:t.lifecycle==='DRAFT'}">{{labels[t.lifecycle]||t.lifecycle}}</span><h3><RouterLink :to="target(t)">{{t.title}}</RouterLink></h3><p>{{t.className}} · {{t.jobName||'未设置岗位'}}</p></div></div><div class="task-entry-time"><span>{{t.lifecycle==='SCHEDULED'?'开放时间':'截止时间'}}</span><strong>{{date(t.lifecycle==='SCHEDULED'?t.startTime:t.deadline)}}</strong><small>至少 {{t.minAttempts}} 次有效训练</small></div><div class="task-entry-execution" v-if="t.publishedAt"><RouterLink :to="target(t,{execution:'COMPLETED'})">已完成 <strong>{{count(t,'COMPLETED')}}</strong> 人</RouterLink><div><RouterLink :to="target(t,{execution:'unfinished'})">待完成 {{participants(t).length-count(t,'COMPLETED')}} 人</RouterLink><RouterLink v-if="late(t)" class="task-late" :to="target(t,{execution:'overdue'})">逾期 {{late(t)}} 人</RouterLink></div><small>参与 {{participants(t).length}} 人 · 减免 {{(t.assignments||[]).length-participants(t).length}} 人</small></div><div class="task-entry-execution" v-else><strong>尚未发布</strong><small>核对问题、参与名单与评价方案</small></div><RouterLink class="task-entry-action" :to="target(t)">{{t.lifecycle==='DRAFT'?'继续编辑':'查看执行'}} →</RouterLink></article></div>
  <div v-else class="task-workbench-empty"><span class="task-decoration briefcase" aria-hidden="true"/><h3>{{overdueView?'当前没有逾期未完成分配':currentClassTasks.length?'没有符合条件的任务':'准备第一项教学训练'}}</h3><p>{{currentClassTasks.length?'调整搜索或状态筛选，查看其他任务。':'选择班级、设定训练问题与评价目标，发布后即可跟进学生执行。'}}</p><button v-if="currentClassTasks.length" @click="set({search:undefined,lifecycle:undefined,view:undefined})">清除搜索与状态</button><RouterLink v-else class="primary" :to="{path:'/teacher/tasks/create',query:{classId:q.classId}}">创建训练任务</RouterLink></div>
  </template>
 </section>
</template>
<script setup>
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {isOverdue} from '../../services/teachingWorkspace.js'
defineEmits(['refresh'])
const props=defineProps({loading:Boolean,tasks:{type:Array,default:()=>[]},classes:{type:Array,default:()=>[]}}),route=useRoute(),router=useRouter(),q=computed(()=>route.query)
const classLayoutPreference=ref(readClassLayout())
function readClassLayout(){try{return localStorage.getItem('teacher-class-layout')}catch{return null}}
const classLayout=computed(()=>['cards','list'].includes(classLayoutPreference.value)?classLayoutPreference.value:props.classes.length>6?'list':'cards')
const filteredClasses=computed(()=>{const term=String(q.value.classSearch||'').trim().toLowerCase();return props.classes.filter(c=>`${c.name} ${c.semester||''}`.toLowerCase().includes(term))})
function changeClassLayout(value){classLayoutPreference.value=value;try{localStorage.setItem('teacher-class-layout',value)}catch{}}
const tabs=[{key:'',name:'全部'},{key:'ACTIVE',name:'进行中'},{key:'DRAFT',name:'草稿'},{key:'SCHEDULED',name:'待开始'},{key:'ENDED',name:'已结束'}],labels={ACTIVE:'进行中',DRAFT:'草稿',SCHEDULED:'待开始',CLOSED:'已截止',ENDED:'已结束'}
const participants=t=>(t.assignments||[]).filter(a=>!a.exempt),count=(t,key)=>participants(t).filter(a=>a.completionStatus===key).length,late=t=>participants(t).filter(a=>isOverdue(a,t)).length
const selectedClass=computed(()=>props.classes.find(c=>String(c.id)===String(q.value.classId))),classTasks=c=>props.tasks.filter(t=>String(t.classId)===String(c.id)),currentClassTasks=computed(()=>selectedClass.value?classTasks(selectedClass.value):[]),publishedClassTasks=computed(()=>currentClassTasks.value.filter(t=>t.publishedAt))
function rate(tasks){const all=tasks.filter(t=>t.publishedAt).flatMap(participants);return all.length?Math.round(all.filter(a=>a.completionStatus==='COMPLETED').length/all.length*100)+'%':'—'}
const completionTasks=computed(()=>publishedClassTasks.value.filter(t=>!q.value.completionTask||String(t.id)===String(q.value.completionTask))),completionTotal=computed(()=>completionTasks.value.flatMap(participants).length),completionDone=computed(()=>completionTasks.value.reduce((n,t)=>n+count(t,'COMPLETED'),0)),completionStates=computed(()=>[{key:'COMPLETED',name:'已完成',color:'#34d399'},{key:'IN_PROGRESS',name:'待完成',color:'#a7e5ce'},{key:'PENDING_VALIDATION',name:'校验中',color:'#f8ce8b'},{key:'NOT_STARTED',name:'未开始',color:'#d4d4d8'}].map(s=>({...s,count:completionTasks.value.reduce((n,t)=>n+count(t,s.key),0)})))
const belongs=(t,key)=>!key||(key==='ENDED'?['ENDED','CLOSED'].includes(t.lifecycle):t.lifecycle===key)
const matches=computed(()=>currentClassTasks.value.filter(t=>`${t.title} ${t.jobName||''}`.toLowerCase().includes(String(q.value.search||'').trim().toLowerCase())))
const rows=computed(()=>matches.value.filter(t=>belongs(t,q.value.lifecycle)).slice().sort((a,b)=>q.value.sort==='unfinished'?(participants(b).length-count(b,'COMPLETED'))-(participants(a).length-count(a,'COMPLETED')):q.value.sort==='published'?String(b.publishedAt||'').localeCompare(String(a.publishedAt||'')):String(a.deadline||'9999').localeCompare(String(b.deadline||'9999'))))
const overdueView=computed(()=>['overdue','completion'].includes(q.value.view)),overdueRows=computed(()=>matches.value.flatMap(t=>participants(t).filter(a=>isOverdue(a,t)).map(a=>({a,t}))))
function set(values){router.replace({query:{...q.value,...values,page:undefined}})}
function target(t,query={}){return {path:'/teacher/tasks/'+t.id+(t.lifecycle==='DRAFT'?'/edit':''),query:{...query,returnTo:route.fullPath}}}
function date(value){if(!value)return '未设置';return new Date(/[Z+]/.test(value)?value:value+'+08:00').toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}
</script>
